# owner: platform
"""Seating charts: students sorted by name, row by row."""


def _sort_key(student):
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _row_line(number, members):
    names = " | ".join(item.display_name for item in members)
    return f"Row {number}: {names}"


def _chunks(items, size):
    starts = range(0, len(items), size)
    return [items[start:start + size] for start in starts]


# ---
def seating_rows(students, per_row):
    """One text line per row, sorted by last name."""
    if per_row <= 0 or not students:
        raise ValueError("need students and a seat count")
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, per_row)
    return [_row_line(num, row)
            for num, row in enumerate(rows, 1)]
